Section HCW.
  Context {HCEIL : HeapCeil}.

Section FreeGlue.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem) (msF : machine_state) (mo : Model) (Q : config -> Prop).
  Variables (s : ast) (LB : list (Z * Z)) (d : depot) (lo : Z) (CH : list (Z * Z)) (ch : chunk) (bs sbs : list byte).

  Let st := a_st s.
  Let TH := a_thr s.
  Let CTX := a_ctx s.
  Let sb := a_sb s.
  Let U := ch_user_beg ch.
  Let size := ch_used ch.
  Let tq := as_tq st.
  Let l := qc_list tq.
  Let k := zlen l.
  Let lb := last l (mkQB 0 0 0 []).
  Let LA := qb_addr lb.
  Let lcount := qb_count lb.
  Let c := kBatchClass.
  Let CHI := icpt_chain (bv_unsigned ra) (bv_unsigned s0) (bv_unsigned sp) (a_top s) CH.
  Let T := utrace 0x90ca0 (bv_unsigned sp) (a_top s) (a_bot s) 30 CHI.
  Let nT := Z.of_nat (length T).
  Let d' := d_put d (depot_hash T) nT.
  Let LB' := lb_remove U LB.

  Hypothesis HR : ltac2:(zQ "10!igb@4$0?5HCEIL?1s?2LB?1m").
  Hypothesis CHIN : In ch (chunk_list st).
  Hypothesis ALLOC : ltac2:(zQ "40!ii9!in0!ine!ioa@3$0$3@1$2?2ch$1").
  Hypothesis AX : ltac2:(zQ "30!ip4!ita!iu6@2$0@2$1?1s?1m@1$2?1m").
  Hypothesis AMX : ltac2:(zQ "10!iv4@3$0?5HCEIL?1s?2mo").
  Hypothesis DEP : ltac2:(zQ "20!me!jjf@3$1$0?1d?1m").
  Hypothesis DPL : ltac2:(zQ "10!jo8@3$0?5HCEIL?1s?1d").
  Hypothesis DFS : ltac2:(zQ "70!jp8!jq4!jqd!jsd!ip4!jt4!jtc@2$4@4$2@1$1?1s$0@1$5?1d@2$3+h0+hggg0@4$2@1$1?1s$0@1$6?1d@2$3+8+ogg0").
  Hypothesis DCOV : ltac2:(zQ "10!ju4@2$0?1d?2mo").
  Hypothesis MI : ltac2:(zQ "20!me!kib@2$1$0?1m").
  Hypothesis ST : ltac2:(zQ "40!kkf!me!kp3!kr7@4$2$1?1m?2lo@2$3@1$0#k0?2sp").
  Hypothesis LO : ltac2:(zQ "20!lg4!lgd@2$1@1$0?5HCEIL?2lo").
  Hypothesis HI0 : ltac2:(zQ "40!kkf!lh3!lgd!kr7@2$2@2$1?2lo+so0@2$3@1$0#k0?2sp").   (* [comment removed for export] *)
  Hypothesis SPA : ltac2:(zQ "50!ii9!kkf!lha!lhf!kr7@3$0$2@2$3@2$4@1$1#k0?2sp+h0Z").
  Hypothesis SPT : ltac2:(zQ "50!kkf!lh3!lgd!li9!kr7@2$2@2$1@2$4@1$0#k0?2sp+h0@2$3+2+if").
  Hypothesis TP : ltac2:(zQ "50!ii9!kkf!lj0!ln2!ln8@3$0@1$4@1$1#k0?2tp@1$3$2").
  Hypothesis DCAP : ltac2:(zQ "60!lh3!ip4!lne!loa!lgd!lp3@2$1@2$5@2$0@1$3?1d+1+hggg0@2$4@2$0@1$2?1d+hf+ogg0").
  Hypothesis FCH : ltac2:(zQ "d0!kkf!kr7!lp9!lra!ls2!ii9!mg8!ip4!me!mh5!mhe!lh3!lgd>0@3$5$3@3$6@1$9?1s@2$1@1$0#k0?2sp@1$2?1s$4>0@3$5$3@3$6@2$1@1$0#k0?2sp@2$1@1$0#k0?2s0@1$2?1s$4@2$7@2$c@2$b@2$1@1$0#k0?2sp+h0@2$1@1$0#k0?2s0@5$a$8?1m@1$2?1s@2$1@1$0#k0?2s0?2CH").
  Hypothesis Ha0 : a0 = wz U.
  (* [comment removed for export] *)
  Hypothesis BLK : rw_cells asegs m U [CB (Z.to_nat size) bs].
  Hypothesis SHB : SHAD m U sbs /\ Z.of_nat (length sbs) = nsh size.
  (* [comment removed for export] *)
  Hypothesis QSZ : size <= kQuarantineMaxSize.
  (* [comment removed for export] *)
  Hypothesis INITQH : INITQ st.
  Hypothesis PINVH : PINVc st.
  Hypothesis NALH : nlive st kBatchClass + 1 <= LIVEC kBatchClass.   (* [comment removed for export] *)
  (* [comment removed for export] *)
  Hypothesis PROOM : pusage st + COLD_COST <= B_PRIM.   (* [comment removed for export] *)
  Hypothesis ROOM : rg_mapped_user (get_region st c) + 2 * kUserMapSize <= kFreeArrayOffset.
